#define MAXSIZE 100
typedef struct {
    int data[MAXSIZE];
    int length;
} SeqList;

questions.answer:
int InsertOrder(SeqList *L, int x)
{
    int i;
    if (L->length >= MAXSIZE)
        return 0;
    i = L->length - 1;
    while (i >= 0 && L->data[i] > x) {
        L->data[i + 1] = L->data[i];
        i--;
    }
    L->data[i + 1] = x;
    L->length++;
    return 1;
}

